  await page.click('.online-entry');check('Offline-origin online entry explains that the Node server must be started',await page.evaluate("Reborn.app.ui.dialog==='network' && document.querySelector('#dialogContent').textContent.includes('npm start')"));await page.click('#dialogFooter [data-act=closeDialog]')
  await page.click('.offline-entry');await page.wait_for_timeout(250)
  check('Country image selection retains all seven countries',await page.locator('.nation-choice img').count()==7)
  check('Allies and enemies are explicit three-way buttons',await page.locator('.role-switch button').count()==18)
