  check('Initial funds input is visible without scrolling at desktop size',await page.evaluate("(()=>{const r=document.getElementById('startMoney').getBoundingClientRect(),d=document.getElementById('dialogContent').getBoundingClientRect();return r.top>=d.top&&r.bottom<=d.bottom;})()"))
  await page.click('[data-act=setupMoney][data-value="25000"]');check('Fund preset changes selected budget',await page.input_value('#startMoney')=='25000')
  await page.fill('#startMoney','32000');await page.locator('#startMoney').blur();check('Custom initial funds are accepted',await page.evaluate('Reborn.app.ui.setup.startMoney===32000'))
  await page.click('[data-act=chooseStyle][data-style=arcade]');check('Arcade style button works',await page.evaluate("Reborn.app.ui.setup.style==='arcade'"))
