  await page.click('[data-act=setupDifficulty][data-value=hard]');check('Difficulty is an explicit selected button',await page.evaluate("Reborn.app.ui.setup.difficulty==='hard'"))
  await page.click('[data-act=setupPrep][data-value="0"]');check('Zero preparation is labeled Off, not 00:00',await page.evaluate("document.querySelector('[data-act=setupPrep][data-value=\"0\"]').textContent===tr('off')"))
  await page.click('[data-act=setupIntel][data-value=false]');check('Full information option updates game setup',await page.evaluate('Reborn.app.ui.setup.intel===false'))
