  await page.click('[data-act=setupIntel][data-value=false]')
  for n in ['russia','china','israel','usa','france','uk']: await page.click(f'[data-act=setupRole][data-nation={n}][data-role=none]')
  check('Starting without any enemy is prevented',await page.locator('[data-act=begin]').is_disabled())
  await page.click('[data-act=setupRole][data-nation=israel][data-role=enemy]');await page.click('[data-act=setupRole][data-nation=russia][data-role=ally]')
  check('A valid roster enables start',not await page.locator('[data-act=begin]').is_disabled())
  await page.screenshot(path=str(OUT/'02-battle-setup.png'))
  await page.click('[data-act=begin]');await page.wait_for_function("Reborn.app.screen==='game'");await page.wait_for_timeout(350);await page.evaluate('Reborn.app.speed=0;Reborn.app.ui.update(true)')
  check('Start transfers selected funds, roster, mode and difficulty',await page.evaluate("Reborn.app.game.options.startMoney===32000 && Reborn.app.game.options.style==='realistic' && Reborn.app.game.options.difficulty==='hard' && Reborn.app.game.factions.length===3 && Reborn.app.game.options.prep===0 && !Reborn.app.game.options.intel"))
  check('Dock has exactly ten primary commands',await page.locator('#quickDock>button').count()==10)
